101	\toprule
102	Signal Pair & MMLU & ARC & GSM8K \\
103	\midrule
104	S1--S2 & $-$0.044 & $-$0.019 & $-$0.022 \\
105	S1--S4 & $+$0.038 & $+$0.009 & $+$0.053 \\
